<section class="panel category-editor-panel"><div class="panel-heading"><h2><?= $model->isNewRecord?'دسته‌بندی جدید':'ویرایش دسته‌بندی' ?></h2><?php if(!$model->isNewRecord): ?><span class="muted note">#<?= (int)$model->id ?></span><?php endif; ?></div>
<?php $form=$this->beginWidget('CActiveForm',array('id'=>'category-form','action'=>array_merge(array('adminCategory/index'),$model->isNewRecord?array():array('id'=>$model->id)),'htmlOptions'=>array('data-pjax-form'=>'1','data-pjax-target'=>'#category-workspace','data-pjax-busy'=>'#category-editor','data-category-id'=>(int)$model->id,'data-saved-parent'=>(int)$model->parent_id,'data-saved-order'=>(int)$model->sort_order))); ?><?= $form->errorSummary($model) ?><?= CHtml::hiddenField('tree_revision',CategoryTreeService::revision()) ?>
<div class="field"><label for="Category_name">نام دسته‌بندی *</label><?= $form->textField($model,'name',array('required'=>true,'maxlength'=>180)) ?></div><div class="field"><label for="Category_slug">شناسه انگلیسی</label><?= $form->textField($model,'slug',array('dir'=>'ltr','maxlength'=>190)) ?></div><div class="field"><label for="Category_parent_id">دسته والد</label><?= $form->dropDownList($model,'parent_id',Category::options($model->id),array('prompt'=>'دسته اصلی / بدون والد')) ?></div><div class="field"><label for="Category_sort_order">ترتیب نمایش</label><?= $form->numberField($model,'sort_order',array('min'=>0)) ?></div><div class="field"><label for="Category_description">توضیحات</label><?= $form->textArea($model,'description',array('class'=>'markdown-editor','rows'=>5)) ?></div><?php $this->widget('MediaPicker',array('name'=>'image_id','value'=>CmsMedia::ids($model->image),'multiple'=>false,'label'=>'تصویر دسته‌بندی')); ?><?= CHtml::submitButton('ذخیره دسته‌بندی',array('class'=>'btn btn-primary btn-block')) ?><?php $this->endWidget(); ?>
<?php if(!$model->isNewRecord): ?><?= CHtml::beginForm(array('adminCategory/delete','id'=>$model->id),'post',array('class'=>'category-delete-form','data-pjax-form'=>'1','data-pjax-target'=>'#category-workspace','data-pjax-busy'=>'#category-editor','data-confirm'=>'دسته‌بندی حذف شود؟ دسته دارای محصول یا زیرمجموعه قابل حذف نیست.')) ?><?= CHtml::submitButton('حذف دسته',array('class'=>'btn btn-danger btn-block')) ?><?= CHtml::endForm() ?><?php endif; ?></section>
